void ItemSpawn::DrawMenu(){
    InitializeItemList();
    static int ItemSpawnAmmount = 1;
    static int StackNumber = 1;
    
    
    strcpy(textfieldBuffer, itemTextField.text.UTF8String);
    string MyString = string("InputText: ") + textfieldBuffer;
    ImGui::Button(MyString.c_str(), ImVec2(ImGui::GetContentRegionAvailWidth() - 10, 20));
    if(ImGui::IsItemHovered()){
        [itemTextField becomeFirstResponder];
    } else{
        [itemTextField resignFirstResponder];
    }

    ImGui::PushStyleVar(ImGuiStyleVar_ChildBorderSize, 0);
    ImGui::PushStyleVar(ImGuiStyleVar_ScrollbarSize, 20);
    ImGui::BeginChild("ChildMain", ImVec2(ImGui::GetContentRegionAvailWidth()-20, 160), true, ImGuiWindowFlags_None);
    ImGui::Indent();
    
    
    string FilterString = textfieldBuffer;
    
    for(const ItemIDStruct& currentItem : Items)
    {
        if(utils.containsIgnoreCase(currentItem.DisplayName, FilterString))
        {
            ImGui::PushItemWidth(200);
                                                
            ImGui::Text("%s", currentItem.DisplayName.c_str());
            
            ImGui::PopItemWidth();
            
            ImGui::SameLine(200);

            ImGui::PushID(currentItem.BlueprintString.c_str());

            if(ImGui::Button("Spawn", ImVec2(150, ImGui::GetFrameHeight()))){
                for(int i = 0; i < StackNumber; i++){
                    functions.ExecuteConsoleCommand(utils.string_format("Admincheat GiveSlotItem \"%s\" %d %d", currentItem.BlueprintString.c_str(), i+3, ItemSpawnAmmount));
                }
            }


            ImGui::PopID();
        }
    }
    
    ImGui::Unindent();
    ImGui::EndChild();
    ImGui::PopStyleVar(2);
    
    ImGui::SliderInt(GetMenuText("Item Spawn Ammount"), &ItemSpawnAmmount, 1, 5000, "%d", ImGuiSliderFlags_Logarithmic);
    ImGui::SliderInt(GetMenuText("Stacks"), &StackNumber, 1, 300);
    
}
